const __pageData = JSON.parse('{"title":"工具 Schema 目录","description":"","frontmatter":{"editSource":"docs/tool-catalog.zh.md"},"headers":[],"relativePath":"reference/tool-catalog.md","filePath":"reference/tool-catalog.md"}');
